<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Feedback,Order,QrScan,ServiceRequest};use Illuminate\Support\Facades\DB;
class AnalyticsController extends Controller{public function __invoke(){return view('admin.analytics',['metrics'=>['qr_scans'=>QrScan::count(),'requests'=>ServiceRequest::count(),'orders'=>Order::count(),'revenue'=>(float)Order::where('status','DELIVERED')->sum('total'),'avg_order'=>(float)Order::avg('total'),'sla_breaches'=>ServiceRequest::where('status','!=','COMPLETED')->where('completion_due_at','<',now())->count(),'needs_attention'=>Feedback::where('rating','needs_attention')->count()],'popular_food'=>DB::table('order_items')->select('item_name',DB::raw('SUM(quantity) qty'))->where('hotel_id',app(\App\Support\TenantContext::class)->requireId())->groupBy('item_name')->orderByDesc('qty')->limit(10)->get()]);}}
